<?php
if(!defined('ABSPATH')){exit(1);}$f=get_option('cvt_custody_fixture');$messenger=absint($f['messenger_id']);wp_set_current_user($messenger);$primary=absint($f['order_id']);
$route=CVD_Order_Transition_Service::transition($primary,'delivery','handed_over',array('actor_user_id'=>$messenger,'idempotency_key'=>'custody-route','source'=>'integration_custody_route','precondition'=>static fn(WC_Order $o)=>absint($o->get_meta('_cvd_messenger_user_id',true))?true:CVD_Order_Transition_Service::PRECONDITION_FAILED,'atomic_mutation'=>static function(WC_Order $o,$f,$t,$a,$at){$o->update_meta_data('_cvd_to_customer_at',$at);}));if(!$route['success']){throw new RuntimeException('handed_over falló: '.$route['error_code']);}
$delivered=CVD_Order_Transition_Service::transition($primary,'delivery','delivered',array('actor_user_id'=>$messenger,'idempotency_key'=>'custody-delivered','source'=>'integration_custody_delivered','coupled_payment_state'=>'pending_return','atomic_mutation'=>static function(WC_Order $o,$f,$t,$a,$at){$o->update_meta_data('_cvd_delivered_by',$a->ID);$o->update_meta_data('_cvd_delivered_at',$at);}));if(!$delivered['success']){throw new RuntimeException('delivered falló: '.$delivered['error_code']);}
foreach(array('failed_order_id'=>'failed','returned_order_id'=>'returned')as$key=>$target){$result=CVD_Order_Transition_Service::transition(absint($f[$key]),'delivery',$target,array('actor_user_id'=>$messenger,'idempotency_key'=>'custody-'.$target,'source'=>'integration_custody_result'));if(!$result['success']){throw new RuntimeException($target.' falló: '.$result['error_code']);}}
echo "OK: ruta, delivered, failed y returned centralizados.\n";
